const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '木塞受力示意图（示意）' },
      { kind: 'text', payload: 'F（拉力）' },
      { kind: 'text', payload: '瓶内气压与摩擦的合力' },
      { kind: 'text', payload: '木塞' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cx = W * 0.30;
    var neckHalf = W * 0.105;
    var bodyHalf = W * 0.26;
    var corkTopY = H * 0.28;
    var corkBotY = H * 0.46;
    var neckTopY = H * 0.33;
    var neckBotY = H * 0.70;
    var bodyTopY = H * 0.90;
    var bottomY = H * 0.95;
    var innerHalf = neckHalf - W * 0.014;
    var upTip = H * 0.13;
    var downTip = H * 0.66;
    var headW = W * 0.028;
    var headL = H * 0.042;
    var ink = '#1F3A5F';

    function rect(x0, y0, x1, y1) {
      return [['M', x0, y0], ['L', x1, y0], ['L', x1, y1], ['L', x0, y1], ['Z']];
    }

    var glass = [
      ['M', cx - neckHalf, neckTopY],
      ['L', cx - neckHalf, neckBotY],
      ['L', cx - bodyHalf, bodyTopY],
      ['L', cx - bodyHalf, bottomY],
      ['L', cx + bodyHalf, bottomY],
      ['L', cx + bodyHalf, bodyTopY],
      ['L', cx + neckHalf, neckBotY],
      ['L', cx + neckHalf, neckTopY],
      ['Z']
    ];

    var outline = [
      ['M', cx - neckHalf, neckTopY],
      ['L', cx - neckHalf, neckBotY],
      ['M', cx - neckHalf, neckBotY],
      ['L', cx - bodyHalf, bodyTopY],
      ['M', cx - bodyHalf, bodyTopY],
      ['L', cx - bodyHalf, bottomY],
      ['M', cx - bodyHalf, bottomY],
      ['L', cx + bodyHalf, bottomY],
      ['M', cx + bodyHalf, bottomY],
      ['L', cx + bodyHalf, bodyTopY],
      ['M', cx + bodyHalf, bodyTopY],
      ['L', cx + neckHalf, neckBotY],
      ['M', cx + neckHalf, neckBotY],
      ['L', cx + neckHalf, neckTopY]
    ];

    var corkRim = rect(cx - innerHalf - 2, corkTopY - 2, cx + innerHalf + 2, corkBotY + 2);
    var corkFace = rect(cx - innerHalf + 2, corkTopY + 2, cx + innerHalf - 2, corkBotY - 2);

    var upShaft = [['M', cx, corkTopY], ['L', cx, upTip + headL * 0.6]];
    var upHead = [['M', cx, upTip], ['L', cx - headW, upTip + headL], ['L', cx + headW, upTip + headL], ['Z']];
    var downShaft = [['M', cx, corkBotY], ['L', cx, downTip - headL * 0.6]];
    var downHead = [['M', cx, downTip], ['L', cx - headW, downTip - headL], ['L', cx + headW, downTip - headL], ['Z']];

    return {
      schemaVersion: 1,
      sceneId: 'cork-force-diagram',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'glass', commands: glass },
        { id: 'glassOutline', commands: outline },
        { id: 'corkRim', commands: corkRim },
        { id: 'corkFace', commands: corkFace },
        { id: 'forceUpShaft', commands: upShaft },
        { id: 'forceUpHead', commands: upHead },
        { id: 'forceDownShaft', commands: downShaft },
        { id: 'forceDownHead', commands: downHead }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'glass', fill: '#DDEDF7' },
          { type: 'path', pathId: 'glassOutline', fill: '#3E6B8A', stroke: { width: 2.4 } },
          { type: 'path', pathId: 'corkRim', fill: '#8A6432' },
          { type: 'path', pathId: 'corkFace', fill: '#D2A15E' },
          { type: 'path', pathId: 'forceUpShaft', fill: ink, stroke: { width: 2.6 } },
          { type: 'path', pathId: 'forceUpHead', fill: ink },
          { type: 'path', pathId: 'forceDownShaft', fill: ink, stroke: { width: 2.6 } },
          { type: 'path', pathId: 'forceDownHead', fill: ink },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: W * 0.5, y: H * 0.035 }, hAlign: 'center', vAlign: 'top', color: ink },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: cx + W * 0.04, y: (upTip + corkTopY) / 2 }, hAlign: 'left', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: W * 0.44, y: (corkBotY + downTip) / 2 }, hAlign: 'left', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: cx, y: (corkTopY + corkBotY) / 2 }, hAlign: 'center', vAlign: 'middle', color: '#3B2A12' }
        ]
      }
    };
  }
};
